"""Inhalt des Questbuchs. Aufgaben/Belohnungen siehe generator.py.

Q(schluessel, titel, aufgaben, text, nach=[...], belohnung=...)
  aufgaben:  'mod:item' | ('item', id, anzahl) | ('kill', mob, anzahl) | ('dim', dimension)
             | ('struct', struktur) | ('biome', biom) | 'check'   (auch als Liste)
  belohnung: XP-Level (int) oder ('item', id, anzahl), auch als Liste
"""

BUCH_TITEL = 'Unser Modpack'
BUCH_ICON = 'minecraft:writable_book'


def Q(key, titel, aufgaben, text=None, nach=(), belohnung=1, sub=None, **kw):
    q = {'key': key, 'titel': titel, 'aufgaben': aufgaben, 'text': text, 'nach': list(nach), 'belohnung': belohnung, 'sub': sub}
    q.update(kw)
    return q


KAPITEL = []


def kapitel(datei, titel, icon, untertitel, quests):
    KAPITEL.append({'datei': datei, 'titel': titel, 'icon': icon, 'untertitel': untertitel, 'quests': quests})


